84	            char c = s.charAt(i);
85	            if (c < '0' || c > '9') {
86	                continue;
87	            }
88	            int d = c - '0';
89	            if (dbl) {
90	                d *= 2;
91	                if (d > 9) {
92	                    d -= 9;
93	                }
94	            }
95	            sum += d;
96	            dbl = !dbl;
97	        }
98	        return (10 - (sum % 10)) % 10;
99	    }
100	
101	    /**
102	     * De-duplicates {@code base} against the {@code existing} member ids: returns {@code base}
103	     * unchanged when it is not already taken, otherwise appends {@code -<n>} with the smallest
104	     * {@code n} of 2 or more that makes the id unique.
105	     */
106	    public static String deduplicate(String base, Set<String> existing) {
107	        if (!existing.contains(base)) {
108	            return base;
109	        }
110	        for (int n = 2; ; n++) {
111	            String candidate = base + "-" + n;
112	            if (!existing.contains(candidate)) {
113	                return candidate;
114	            }
115	        }
116	    }
117	
118	    /**
119	     * The {@code REGION} segment of a member id — its leading letters, before the two-digit fiscal
120	     * year — or {@code null} when there is no id to read it from.
121	     */
122	    public static String region(String memberId) {
123	        if (memberId == null) {
124	            return null;
125	        }
126	        int i = 0;
127	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
128	            i++;
129	        }
130	        return i == 0 ? null : memberId.substring(0, i);
131	    }
132	
133	    /**
134	     * The {@code FY<YY>} fiscal-year label read from a member id's {@code FY} segment (the two
135	     * characters after the region), or {@code null} when there is no id or it is too short to carry
136	     * one. The {@code FY} prefix is applied by {@link OwnerFiscalYear#label(String)}, which owns the
137	     * label format.
138	     */
139	    public static String fiscalYearLabel(String memberId) {
140	        String region = region(memberId);
141	        if (region == null || memberId.length() < region.length() + 2) {
142	            return null;
143	        }
144	        return OwnerFiscalYear.label(memberId.substring(region.length(), region.length() + 2));
145	    }
146	}
