13	/**
14	 * Emits audit records on the dedicated {@code AUDIT} logger once a new owner has been persisted.
15	 *
16	 * <p>Two records are emitted:
17	 * <ul>
18	 * <li>a human-readable audit line carrying the owner id, the {@code memberId}, the
19	 * {@code registrationDate} and the {@code membershipLevel}; and</li>
20	 * <li>an immutable structured JSON event
21	 * {@code {seq, ownerId, memberId, membershipLevel, event:"OWNER_CREATED"}}, where {@code seq}
22	 * is a monotonically increasing integer across every create in this process.</li>
23	 * </ul>
24	 *
25	 * <p>The event's identifier is read through {@link OwnerPrimaryIdentifier}, so it always carries the
26	 * owner's current primary identifier &mdash; the unified {@code memberId}.
27	 */
28	public class AuditOwnerCreated {
29	
30	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
31	
32	    private static final JsonMapper JSON = JsonMapper.shared();
33	
34	    /** Monotonically increasing sequence across every owner created in this process. */
35	    private static final AtomicLong SEQ = new AtomicLong();
36	
37	    public void service(@Val Owner owner) {
38	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
39	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
40	                owner.getMembershipLevel());
41	
42	        ObjectNode event = JSON.createObjectNode();
43	        event.put("seq", SEQ.incrementAndGet());
44	        event.put("ownerId", owner.getId());
45	        event.put("memberId", OwnerPrimaryIdentifier.of(owner));
46	        event.put("membershipLevel", owner.getMembershipLevel());
47	        event.put("event", "OWNER_CREATED");
48	        AUDIT.info(JSON.writeValueAsString(event));
49	    }
50	}
